      plasma: function () { tone('sawtooth', 900, 220, 0.12, 0.12); tone('sine', 1400, 500, 0.1, 0.1); },
      reload: function () { tone('square', 500, 480, 0.04, 0.06); setTimeout(function () { tone('square', 700, 680, 0.04, 0.06); }, 260); },
      empty: function () { tone('square', 300, 290, 0.03, 0.05); },
      hit: function () { noise(0.12, 900, 200, 0.4, 2); },
