      if (a.type === 'spitter') part('sph', M4.chain(body, tr(0, 1.33, -0.14), sc(0.15, 0.13, 0.13)), [0.4, 0.8, 0.25], [0.25 + Math.sin(time * 6) * 0.1, 0.7, 0.12]);
