        pd('box', M4.chain(M4.T(0, 0.012, -0.05), M4.S(0.034, 0.03, 0.15)), [0.26, 0.27, 0.3]);          // slide
        pd('box', M4.chain(M4.T(0, -0.012, -0.045), M4.S(0.03, 0.022, 0.13)), [0.16, 0.16, 0.18]);       // frame
        pd('cyl', M4.chain(M4.T(0, 0.012, -0.125), M4.Rx(-Math.PI / 2), M4.S(0.008, 0.01, 0.008)), [0.05, 0.05, 0.05]);
