      parts.forEach(function (p) { draw(PRIM.box, M4.chain(M4.T(p.x, p.y, p.z), M4.S(p.s, p.s, p.s)), p.col, p.emis ? p.emis.map(function (v) { return v * Math.min(1, p.life * 2); }) : null); });
      // transparent / glowing things last
