      // soft contact shadow: a faded dark spot under the feet (no hard edge)
      aliens.forEach(function (a) { if (a.type !== 'drone' && !a.dead) draw(PRIM.quad, M4.chain(M4.T(a.x, 0.025 + groundAt(a.x, a.z), a.z), M4.Rx(-Math.PI / 2), M4.S(a.t.r * 2.6, a.t.r * 2.2, 1)), [0, 0, 0], null, T.glow, 0.5, true); });
