      draw(PRIM.cyl, M4.chain(M4.T(0, 0, -93), M4.S(0.6, 30, 0.6)), [0.3 * beamA, 1.2 * beamA, 0.5 * beamA], null, null, 1, true);
      halos.forEach(function (h) { billboard(h.p, h.s, h.c, P.yaw, P.pitch); });
