      gl.clear(gl.DEPTH_BUFFER_BIT);
      gl.uniformMatrix4fv(U.uVP, false, M4.mul(M4.persp(0.85, W_ / H_, 0.01, 10), view));   // narrower lens for the gun, as shooters do
      drawGun(view);
